private long calculateMaxDifferenceSum(int[] A) {
    long totalSum = 0;
    int N = A.length;
    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            int diff = A[j] - A[i];
            if (diff > 0) {
                totalSum += diff;
            }
        }
    }
    return totalSum;
}
